import{_ as a,o as t,c as n,ae as i}from"./chunks/framework.Co1PSFSm.js";const h=JSON.parse('{"title":"Core Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"docs/workflow.md","filePath":"docs/workflow.md"}'),o={name:"docs/workflow.md"};function r(s,e,l,c,u,d){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="core-workflow" tabindex="-1">Core Workflow <a class="header-anchor" href="#core-workflow" aria-label="Permalink to &quot;Core Workflow&quot;">​</a></h1><p>The typical research process in CM Transcription Equivalents follows these three main sequential steps. For detailed instructions on each step, follow the links to the dedicated feature pages.</p><h2 id="_1-equivalents-management" tabindex="-1">1. Equivalents Management <a class="header-anchor" href="#_1-equivalents-management" aria-label="Permalink to &quot;1. Equivalents Management&quot;">​</a></h2><p>Before annotating physical scans, you define the &quot;Equivalents&quot; – the mapping between abstract transcription patterns and their Reference IDs.</p><ul><li>Import your transcription data to see aggregated pattern frequencies.</li><li>Assign stable <strong>Ref IDs</strong> to these patterns in a central workspace.</li><li><em>See <a href="./equivalents.html">Equivalents Management</a> for detailed usage.</em></li></ul><h2 id="_2-manuscript-annotation" tabindex="-1">2. Manuscript Annotation <a class="header-anchor" href="#_2-manuscript-annotation" aria-label="Permalink to &quot;2. Manuscript Annotation&quot;">​</a></h2><p>Once your base patterns are defined, you move to the visual phase: linking those patterns to physical ink on the scans.</p><ul><li>Load a manuscript via its IIIF manifest.</li><li>Draw bounding boxes (Line Regions) around individual lines of music.</li><li>Draw precise polygons around individual neumes and link them to specific occurrences in your transcription data.</li><li><em>See <a href="./annotation.html">Manuscript Annotation</a> for detailed usage.</em></li></ul><h2 id="_3-public-documentation" tabindex="-1">3. Public Documentation <a class="header-anchor" href="#_3-public-documentation" aria-label="Permalink to &quot;3. Public Documentation&quot;">​</a></h2><p>After your analysis and annotation are complete, you can generate an interactive website to share your findings.</p><ul><li>The tool generates a searchable directory of annotated manuscripts.</li><li>It builds an interactive visual gallery where users can hover over manuscript lines to see the underlying transcription data.</li><li><em>See <a href="./public-view.html">Public Documentation</a> for detailed usage.</em></li></ul>',11)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
